var i={nom:"FACT Immobilier",creation:2013,demarrage:2014,adresse:"Cocody Riviera 3, Cit\xE9 Allabra, R\xE9sidence GT",ville:"Abidjan, C\xF4te d\u2019Ivoire",telephones:[{libelle:"27 22 46 91 38",lien:"tel:+2252722469138"},{libelle:"05 55 43 55 55",lien:"tel:+2250555435555"}],email:"info@factimmobilier-ci.com",whatsapp:"https://wa.me/2250555435555",valeurs:[{titre:"S\xE9rieux",texte:"Des engagements tenus, des comptes clairs et un suivi \xE9crit de chaque dossier.",icone:"bouclier"},{titre:"Dynamisme",texte:"Une \xE9quipe pr\xE9sente sur le terrain, qui r\xE9pond vite et relance pour vous.",icone:"synchro"},{titre:"Professionnalisme",texte:"Des m\xE9thodes rigoureuses, de l\u2019\xE9tat des lieux \xE0 la remise des cl\xE9s.",icone:"etoile"}]},n=()=>new Date().getFullYear()-i.demarrage,s=[{slug:"gestion-immobiliere",code:"GESTION",titre:"Gestion immobili\xE8re",court:"Gestion locative",accroche:"Votre bien lou\xE9, entretenu et suivi, sans vous en occuper.",icone:"gestion",texte:["Nous trouvons vos locataires, v\xE9rifions leurs dossiers, r\xE9digeons les baux et r\xE9alisons les \xE9tats des lieux d\u2019entr\xE9e et de sortie.","Chaque mois, nous encaissons les loyers, relan\xE7ons les retards et vous remettons un relev\xE9 clair : loyers re\xE7us, honoraires, travaux, montant revers\xE9.","Une panne ? Nous faisons intervenir un prestataire, suivons les travaux et vous demandons votre accord au-del\xE0 du montant fix\xE9 dans votre mandat."],etapes:[{titre:"Visite et estimation",texte:"Nous visitons votre bien et proposons un loyer juste pour le quartier."},{titre:"Signature du mandat",texte:"Dur\xE9e, honoraires et seuil de travaux : tout est \xE9crit."},{titre:"Mise en location",texte:"Annonce, visites, s\xE9lection du locataire, bail et \xE9tat des lieux."},{titre:"Gestion au quotidien",texte:"Loyers, relances, entretien, relev\xE9 de gestion r\xE9gulier."}],appel:{libelle:"Confier mon bien",lien:"/confier-mon-bien"}},{slug:"transactions",code:"TRANSACTION",titre:"Transactions immobili\xE8res",court:"Achat, vente, location",accroche:"Acheter, vendre ou louer en toute s\xE9curit\xE9.",icone:"transaction",texte:["Vous cherchez un logement ou un local : nous vous proposons des biens visit\xE9s et v\xE9rifi\xE9s, et vous accompagnons jusqu\u2019\xE0 la remise des cl\xE9s.","Vous vendez : nous estimons votre bien au prix du march\xE9, le pr\xE9sentons aux bons acqu\xE9reurs et s\xE9curisons la vente jusqu\u2019\xE0 la signature."],etapes:[{titre:"Votre besoin",texte:"Budget, quartier, type de bien : nous pr\xE9cisons ensemble votre recherche."},{titre:"S\xE9lection et visites",texte:"Nous vous pr\xE9sentons des biens qui correspondent vraiment."},{titre:"V\xE9rifications",texte:"Documents du bien et du propri\xE9taire contr\xF4l\xE9s avant tout engagement."},{titre:"Signature",texte:"Bail ou acte de vente, \xE9tat des lieux et remise des cl\xE9s."}],appel:{libelle:"Faire estimer mon bien",lien:"/devis"}},{slug:"construction",code:"CONSTRUCTION",titre:"Construction",court:"Du terrain aux cl\xE9s",accroche:"De l\u2019achat du terrain \xE0 la livraison, un seul interlocuteur.",icone:"construction",texte:["Nous vous accompagnons \xE0 chaque \xE9tape de votre projet : v\xE9rification du terrain, plans, autorisations, choix des entreprises et suivi du chantier.","Vous suivez l\u2019avancement des travaux et le budget, et nous vous remettons un ouvrage conforme \xE0 ce qui a \xE9t\xE9 convenu."],etapes:[{titre:"\xC9tude du projet",texte:"Vos besoins, votre budget, votre terrain."},{titre:"Plans et autorisations",texte:"Conception, devis d\xE9taill\xE9 et d\xE9marches administratives."},{titre:"Chantier",texte:"Suivi r\xE9gulier, contr\xF4le de la qualit\xE9 et des d\xE9lais."},{titre:"Livraison",texte:"R\xE9ception des travaux et remise des cl\xE9s."}],appel:{libelle:"Demander un devis",lien:"/devis"}},{slug:"travaux",code:"TRAVAUX",titre:"Travaux et r\xE9novation",court:"Entretien, r\xE9novation",accroche:"R\xE9nover, r\xE9parer, remettre en \xE9tat avant relocation.",icone:"travaux",texte:["Plomberie, \xE9lectricit\xE9, peinture, \xE9tanch\xE9it\xE9, menuiserie : nous faisons intervenir des prestataires de confiance et contr\xF4lons le travail rendu.","Pour un logement \xE0 relouer ou un bien \xE0 valoriser, nous \xE9tablissons un devis clair et suivons les travaux jusqu\u2019\xE0 leur r\xE9ception."],etapes:[{titre:"Constat",texte:"Visite sur place et description pr\xE9cise des travaux."},{titre:"Devis",texte:"Un montant clair, soumis \xE0 votre accord."},{titre:"R\xE9alisation",texte:"Travaux suivis, photos avant et apr\xE8s."},{titre:"R\xE9ception",texte:"Contr\xF4le final et co\xFBt r\xE9el communiqu\xE9."}],appel:{libelle:"Demander un devis",lien:"/devis"}}],o=["Studio","Appartement","Villa","Duplex","Bureau","Magasin","Entrep\xF4t","Terrain","Immeuble"];function a(e){let t=r(e.prix);return e.operation==="LOCATION"?`${t} FCFA / mois`:`${t} FCFA`}function r(e){return Math.round(e).toLocaleString("fr-FR").replace(/[\u202f\u00a0]/g," ")}export{i as a,n as b,s as c,o as d,a as e,r as f};
